INSERT INTO `question` (`id`, `idQuestion`, `question`, `level`, `score`, `domain`) VALUES
(3, 'ManipulateDataUsingStringBuilder102', '{\n  \"format\" : \"TEXT_UP_COD\",\n  \"type\" : \"MIDLELEVELQUESTION\",\n  \"id\" : \"ManipulateDataUsingStringBuilder102\",\n  \"mainObjectives\" : [ {\n    \"id\" : \"9\",\n    \"name\" : \"Working with Selected classes from the Java API\"\n  } ],\n  \"secondaryObjectives\" : [ {\n    \"id\" : \"92\",\n    \"name\" : \"Manipulate data using the StringBuilder class and its methods\"\n  } ],\n  \"estimateSeconds\" : 100,\n  \"Content\" : {\n    \"text\" : {\n      \"textUP\" : \"What is the output if this class is run with java Indexing cars carts?\",\n      \"code\" : \"public class Indexing {\\n            public static void main(String... books) {\\n                StringBuilder sb = new StringBuilder();\\n                for (String book : books)\\n                    sb.insert(sb.indexOf(\\\"c\\\"), book);\\n                System.out.println(sb);\\n            }\\n        }\"\n    }\n  },\n  \"responses\" : [ {\n    \"respoonse\" : \"cars\"\n  }, {\n    \"respoonse\" : \"cars carts\"\n  }, {\n    \"respoonse\" : \"ccars arts\"\n  }, {\n    \"respoonse\" : \"The code does not compile.\"\n  }, {\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\n  } ],\n  \"answers\" : [ {\n    \"answer\" : false\n  }, {\n    \"answer\" : false\n  }, {\n    \"answer\" : false\n  }, {\n    \"answer\" : false\n  }, {\n    \"answer\" : true\n  } ],\n  \"hint\" : \"Use invalid index\"\n}', 'MIDLELEVELQUESTION', 0, ''),
